void kernel_restart_prepare(char *cmd)
{
	blocking_notifier_call_chain(&reboot_notifier_list, SYS_RESTART, cmd);
	system_state = SYSTEM_RESTART;
	usermodehelper_disable();
	device_shutdown();
}

kernel_restart.body:
void kernel_restart(char *cmd)
{
	kernel_restart_prepare(cmd);
	migrate_to_reboot_cpu();
	syscore_shutdown();
	if (!cmd)
		pr_emerg("Restarting system\n");
	else
		pr_emerg("Restarting system with command '%s'\n", cmd);
	kmsg_dump(KMSG_DUMP_RESTART);
	machine_restart(cmd);
}

ralink_restart.body:
static void ralink_restart(char *command)
{
	if (IS_ENABLED(CONFIG_PCI)) {
		rt_sysc_m32(0, RSTCTL_RESET_PCI, SYSC_REG_RESET_CTRL);
		mdelay(50);
	}

	local_irq_disable();
	rt_sysc_w32(RSTCTL_RESET_SYSTEM, SYSC_REG_RESET_CTRL);
	unreachable();
}

machine_restart.body:
void machine_restart(char *command)
{
	if (_machine_restart)
		_machine_restart(command);

#ifdef CONFIG_SMP
	preempt_disable();
	smp_send_stop();
#endif
	do_kernel_restart(command);
	mdelay(1000);
	pr_emerg("Reboot failed -- System halted\n");
	local_irq_disable();
	while (1);
}

device_shutdown.body:
void device_shutdown(void)
{
	struct device *dev, *parent;

	cpufreq_suspend();

	spin_lock(&devices_kset->list_lock);
	/*
	 * Walk the devices list backward, shutting down each in turn.
	 * Beware that device unplug events may also start pulling
	 * devices offline, even as the system is shutting down.
	 */
	while (!list_empty(&devices_kset->list)) {
		dev = list_entry(devices_kset->list.prev, struct device,
				kobj.entry);

		/*
		 * hold reference count of device's parent to
		 * prevent it from being freed because parent's
		 * lock is to be held
		 */
		parent = get_device(dev->parent);
		get_device(dev);
		/*
		 * Make sure the device is off the kset list, in the
		 * event that dev->*->shutdown() doesn't remove it.
		 */
		list_del_init(&dev->kobj.entry);
		spin_unlock(&devices_kset->list_lock);

		/* hold lock to avoid race with probe/release */
		if (parent)
			device_lock(parent);
		device_lock(dev);

		/* Don't allow any more runtime suspends */
		pm_runtime_get_noresume(dev);
		pm_runtime_barrier(dev);

		if (dev->class && dev->class->shutdown) {
			if (initcall_debug)
				dev_info(dev, "shutdown\n");
			dev->class->shutdown(dev);
		} else if (dev->bus && dev->bus->shutdown) {
			if (initcall_debug)
				dev_info(dev, "shutdown\n");
			dev->bus->shutdown(dev);
		} else if (dev->driver && dev->driver->shutdown) {
			if (initcall_debug)
				dev_info(dev, "shutdown\n");
			dev->driver->shutdown(dev);
		}

		device_unlock(dev);
		if (parent)
			device_unlock(parent);

		put_device(dev);
		put_device(parent);

		spin_lock(&devices_kset->list_lock);
	}
	spin_unlock(&devices_kset->list_lock);
}

pci_device_shutdown.body:
static void pci_device_shutdown(struct device *dev)
{
	struct pci_dev *pci_dev = to_pci_dev(dev);
	struct pci_driver *drv = pci_dev->driver;

	pm_runtime_resume(dev);

	if (drv && drv->shutdown)
		drv->shutdown(pci_dev);
	pci_msi_shutdown(pci_dev);
	pci_msix_shutdown(pci_dev);

#ifdef CONFIG_KEXEC_CORE
	/*
	 * If this is a kexec reboot, turn off Bus Master bit on the
	 * device to tell it to not continue to do DMA. Don't touch
	 * devices in D3cold or unknown states.
	 * If it is not a kexec reboot, firmware will hit the PCI
	 * devices with big hammer and stop their DMA any way.
	 */
	if (kexec_in_progress && (pci_dev->current_state <= PCI_D3hot))
		pci_clear_master(pci_dev);
#endif
}

ra2880stop.body:
void ra2880stop(struct END_DEVICE *ei_local)
{
	unsigned int reg_value;

	pr_info("ra2880stop()...");

	reg_value = sys_reg_read(DMA_GLO_CFG);
	reg_value &= ~(TX_WB_DDONE | RX_DMA_EN | TX_DMA_EN);
	sys_reg_write(DMA_GLO_CFG, reg_value);
	/* QDMA owns TX/FQ memory even when RX packets use PDMA. */
	if (ei_local->features & FE_QDMA) {
		reg_value = sys_reg_read(QDMA_GLO_CFG);
		reg_value &= ~(TX_WB_DDONE | RX_DMA_EN | TX_DMA_EN);
		sys_reg_write(QDMA_GLO_CFG, reg_value);
	}

	pr_info("Done\n");
}

fe_pdma_wait_dma_idle.body:
int fe_pdma_wait_dma_idle(void)
{
	unsigned int loop_cnt;

	/* A failed idle observation never authorizes freeing a DMA owner. */
	for (loop_cnt = 0; loop_cnt < 1000; loop_cnt++) {
		if (!(sys_reg_read(PDMA_GLO_CFG) & (RX_DMA_BUSY | TX_DMA_BUSY)))
			return 0;
		udelay(10);
	}
	pr_err("PDMA did not become idle\n");
	return -ETIMEDOUT;
}

fe_qdma_wait_dma_idle.body:
int fe_qdma_wait_dma_idle(void)
{
	unsigned int loop_cnt;

	/* A failed idle observation never authorizes freeing a DMA owner. */
	for (loop_cnt = 0; loop_cnt < 1000; loop_cnt++) {
		if (!(sys_reg_read(QDMA_GLO_CFG) & (RX_DMA_BUSY | TX_DMA_BUSY)))
			return 0;
		udelay(10);
	}
	pr_err("QDMA did not become idle\n");
	return -ETIMEDOUT;
}

ei_stop_dma.body:
static int ei_stop_dma(struct net_device *dev)
{
	struct END_DEVICE *ei_local = netdev_priv(dev);
	int pdma_err, qdma_err = 0;

	ra2880stop(ei_local);
	pdma_err = fe_pdma_wait_dma_idle();
	if (ei_local->features & FE_QDMA)
		qdma_err = fe_qdma_wait_dma_idle();
	if (pdma_err || qdma_err) {
		/* Keep all owners and the module pin; a timeout is not DMA retirement. */
		ei_local->dma_quarantined = true;
		pr_err("%s: DMA stop failed (%d/%d); keeping rings, reopen blocked\n",
		       dev->name, pdma_err, qdma_err);
		return pdma_err ? pdma_err : qdma_err;
	}
	return 0;
}

raether_shutdown.body:
static void raether_shutdown(struct platform_device *pdev)
{
	struct net_device *dev = platform_get_drvdata(pdev);
	struct END_DEVICE *ei_local;
	struct net_device *pseudo;
	int err;

	if (!dev)
		return;
	ei_local = netdev_priv(dev);
	rtnl_lock();
	WRITE_ONCE(ei_local->dma_quarantined, true);
	pseudo = ei_local->pseudo_dev;
	netif_device_detach(dev);
	if (pseudo)
		netif_device_detach(pseudo);
	rtnl_unlock();
	/* Readers can need RTNL: retire publication without holding it. */
	mii_mgr_detach();
	debug_proc_exit();
	rtnl_lock();
	netif_tx_disable(dev);
	if (pseudo)
		netif_tx_disable(pseudo);
	if (ei_local->kreset_task) {
		kthread_stop(ei_local->kreset_task);
		ei_local->kreset_task = NULL;
	}
	if (ei_local->kphy_poll_task) {
		kthread_stop(ei_local->kphy_poll_task);
		ei_local->kphy_poll_task = NULL;
	}
	fe_int_disable(dev);
	err = ei_stop_dma(dev);
	if (err)
		pr_err("%s: shutdown DMA stop failed (%d); keeping all owners\n",
		       dev->name, err);
	/* Keep rings, MMIO, clocks and existing module/parent references even
 * after idle. Foreign consumers are not retired by device_shutdown().
 * The void shutdown API cannot veto the subsequent machine reset. */
	rtnl_unlock();
}

RtmpDmaQuarantine.body:
VOID RtmpDmaQuarantine(RTMP_ADAPTER *pAd)
{
	POS_COOKIE obj = (POS_COOKIE)pAd->OS_Cookie;
	ULONG flags;

	if (!IS_PCI_INF(pAd) && !IS_PCIE_INF(pAd))
		return;
	spin_lock_irqsave(&((POS_COOKIE)pAd->OS_Cookie)->dma_state_lock, flags);
	pAd->dma_quarantined = TRUE;
	pAd->dma_stopping = TRUE;
	spin_unlock_irqrestore(&((POS_COOKIE)pAd->OS_Cookie)->dma_state_lock, flags);
	RTMP_SET_FLAG(pAd, fRTMP_ADAPTER_HALT_IN_PROGRESS);
	RTMP_CLEAR_FLAG(pAd, fRTMP_ADAPTER_START_UP);
	if (RTMP_TEST_FLAG(pAd, fRTMP_ADAPTER_INTERRUPT_ACTIVE))
		RTMP_ASIC_INTERRUPT_DISABLE(pAd);
	if (pAd->net_dev) {
		netif_tx_stop_all_queues(pAd->net_dev);
		netif_carrier_off(pAd->net_dev);
	}
	/* Containment only: clear-master and idle bits do not prove PCI drain.
	 * Retain adapter, rings/token, IRQ, netdev, BAR, PCI and module owners.
	 * No dev_hold is taken, since unregister waits for netdev references.
	 */
	pci_clear_master(obj->pci_dev);
	MTWF_LOG(DBG_CAT_INIT, DBG_SUBCAT_ALL, DBG_LVL_ERROR,
		("%s: retaining complete PCI DMA owner graph until independent recovery\n", __func__));
}

RtmpDmaTeardownCheck.body:
BOOLEAN RtmpDmaTeardownCheck(RTMP_ADAPTER *pAd)
{
	BOOLEAN done;
	ULONG flags;

	if (!IS_PCI_INF(pAd) && !IS_PCIE_INF(pAd))
		return TRUE;
	spin_lock_irqsave(&((POS_COOKIE)pAd->OS_Cookie)->dma_state_lock, flags);
	if (pAd->dma_quarantined) {
		spin_unlock_irqrestore(&((POS_COOKIE)pAd->OS_Cookie)->dma_state_lock, flags);
		return FALSE;
	}
	pAd->dma_stopping = TRUE;
	done = !pAd->dma_lifecycle_pinned || pAd->dma_quiesced;
	spin_unlock_irqrestore(&((POS_COOKIE)pAd->OS_Cookie)->dma_state_lock, flags);
	if (done) {
		/* Cached hardware idle does not retire a partial software stage. */
		if ((pAd->tm_qm_ops || pAd->tm_hif_ops ||
			READ_ONCE(pAd->qm_wq_state) || READ_ONCE(pAd->hif_wq_state)) &&
			tm_quiesce(pAd) != NDIS_STATUS_SUCCESS) {
			RtmpDmaQuarantine(pAd);
			return FALSE;
		}
		return TRUE;
	}
	RTMP_SET_FLAG(pAd, fRTMP_ADAPTER_HALT_IN_PROGRESS);
	if (pAd->dma_irq_registered) {
		if (RTMP_TEST_FLAG(pAd, fRTMP_ADAPTER_INTERRUPT_ACTIVE))
			RTMP_ASIC_INTERRUPT_DISABLE(pAd);
		synchronize_irq(pAd->net_dev->irq);
	}
	/* Joining execution contexts is not a DMA unmap. Keep queues and ops
	 * available until the hardware stop has actually been accepted.
	 */
	if (tm_quiesce(pAd) != NDIS_STATUS_SUCCESS) {
		RtmpDmaQuarantine(pAd);
		return FALSE;
	}
	AndesDmaQuiesce(pAd);
	if (!RT28XXDMAReset(pAd)) {
		RtmpDmaQuarantine(pAd);
		return FALSE;
	}
	spin_lock_irqsave(&((POS_COOKIE)pAd->OS_Cookie)->dma_state_lock, flags);
	pAd->dma_quiesced = TRUE;
	spin_unlock_irqrestore(&((POS_COOKIE)pAd->OS_Cookie)->dma_state_lock, flags);
	return TRUE;
}

RT28XXDMAStop.body:
BOOLEAN RT28XXDMAStop(RTMP_ADAPTER *pAd)
{
	if (AsicSetWPDMA(pAd, PDMA_TX_RX, FALSE) != TRUE)
		return FALSE;

	/* This is the chip's PDMA idle acknowledgement, not a PCI drain proof. */
	return AsicWaitPDMAIdle(pAd, 200, 1000) == TRUE;
}

RT28XXDMAReset.body:
BOOLEAN RT28XXDMAReset(RTMP_ADAPTER *pAd)
{
	if (!RT28XXDMAStop(pAd))
		return FALSE;

	return AsicResetWPDMA(pAd);
}

rt_pci_shutdown.body:
static VOID rt_pci_shutdown(struct pci_dev *pci_dev)
{
	/* Ordinary reboot does not clear bus mastering in the PCI core.  Keep
	 * all DMA ownership intact here: disabling new transactions is not an
	 * acknowledgement that the device has completed in-flight DMA.
	 */
	pci_clear_master(pci_dev);
}
